textContent:
Given a fraction, find a recurring sequence of digits if it exists, otherwise, print "No recurring sequence".Examples:Input  : Numerator = 8, Denominator = 3Output : Recurring sequence is 6 Explanation : 8/3 = 2.66666666.......  Input : Numerator = 50, Denominator = 22Output : Recurring sequence is 27Explanation : 50/22 = 2.272727272..... Input : Numerator = 11, Denominator = 2Output : No recurring sequenceExplanation : 11/2 = 5.5Try It YourselfWhen does the fractional part repeat?Let us simulate the process of converting fractions to decimals. Let us look at the part where we have already figured out the integer part, which is floor(numerator/denominator). Now we are left with ( remainder = numerator%denominator ) / denominator. If you remember the process of converting to decimal, at each step we do the following : Multiply the remainder by 10.Append the remainder/denominator to the result.Remainder = remainder % denominator.At any moment, if the remainder becomes 0, we are done.However, when there is a recurring sequence, the remainder never becomes 0. For example, if you look at 1/3, the remainder never becomes 0.Below is one important observation : If we start with the remainder 'rem' and if the remainder repeats at any point in time, the digits between the two occurrences of 'rem' keep repeating.So the idea is to store seen remainders in a map. Whenever a remainder repeats, we return the sequence before the next occurrence. Below is the implementation of the above idea. 
            C++

    // C++ program to find repeating 
// sequence in a fraction
#include <bits/stdc++.h>
using namespace std;

// This function returns repeating sequence of
// a fraction.  If repeating sequence doesn't
// exist, then returns empty string
string fractionToDecimal(int numr, int denr)
{
    string res; // Initialize result

    // Create a map to store already 
    // seen remainders, remainder is used
    // as key and its position in
    // result is stored as value.
    // Note that we need
    // position for cases like 1/6. 
    // In this case,the recurring sequence 
    // doesn't start from first
    // remainder.
    map<int, int> mp;
    mp.clear();

    // Find first remainder
    int rem = numr % denr;

    // Keep finding remainder until either remainder
    // becomes 0 or repeats
    while ((rem != 0) 
           && (mp.find(rem) == mp.end()))
    {
        // Store this remainder
        mp[rem] = res.length();

        // Multiply remainder with 10
        rem = rem * 10;

        // Append rem / denr to result
        int res_part = rem / denr;
        res += to_string(res_part);

        // Update remainder
        rem = rem % denr;
    }

    return (rem == 0) ? "" : res.substr(mp[rem]);
}

// Driver code
int main()
{
    int numr = 50, denr = 22;
    string res = fractionToDecimal(numr, denr);
    if (res == "")
        cout << "No recurring sequence";
    else
        cout << "Recurring sequence is " << res;
    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>
#include <string.h>

// This function returns repeating sequence of
// a fraction. If repeating sequence doesn't
// exist, then returns empty string
char* fractionToDecimal(int numr, int denr) {
    // Initialize result
    char* res = (char*)malloc(1000);
    int index = 0;
    int rem;
    int seen[1000] = {0}; // Array to store already seen remainders

    // Find first remainder
    rem = numr % denr;

    // Keep finding remainder until either remainder
    // becomes 0 or repeats
    while (rem != 0 && seen[rem] == 0) {
        // Store this remainder
        seen[rem] = index + 1; // Store position + 1

        // Multiply remainder with 10
        rem *= 10;

        // Append rem / denr to result
        int res_part = rem / denr;
        res[index++] = res_part + '0';

        // Update remainder
        rem = rem % denr;
    }

    if (rem == 0) {
        res[index] = '\0';
        return ""; // No recurring sequence
    } else {
        // Find the position to insert '('
        int pos = seen[rem] - 1;
        memmove(res + pos + 1, res + pos, index - pos);
        res[pos] = '(';
        res[index + 1] = ')';
        res[index + 2] = '\0';
        return res;
    }
}

// Driver code
int main() {
    int numr = 50, denr = 22;
    char* res = fractionToDecimal(numr, denr);
    if (strlen(res) == 0)
        printf("No recurring sequence");
    else
        printf("Recurring sequence is %s", res);
    free(res);
    return 0;
}


            Java

    // Java program to find
// repeating sequence
// in a fraction
import java.util.*;
class GFG {

    // This function returns repeating
    // sequence of a fraction. If
    // repeating sequence doesn't
    // exist, then returns empty String
    static String fractionToDecimal(int numr, int denr)
    {
        // Initialize result
        String res = "";

        // Create a map to store already
        // seen remainders. Remainder is
        // used as key and its position in
        // result is stored as value.
        // Note that we need position for
        // cases like 1/6.  In this case,
        // the recurring sequence doesn't
        // start from first remainder.
        HashMap<Integer, Integer> mp = new HashMap<>();
        mp.clear();

        // Find first remainder
        int rem = numr % denr;

        // Keep finding remainder until
        //  either remainder becomes 0 or repeats
        while ((rem != 0) && (!mp.containsKey(rem))) 
        {
            // Store this remainder
            mp.put(rem, res.length());

            // Multiply remainder with 10
            rem = rem * 10;

            // Append rem / denr to result
            int res_part = rem / denr;
            res += String.valueOf(res_part);

            // Update remainder
            rem = rem % denr;
        }

        if (rem == 0)
            return "";
        else if (mp.containsKey(rem))
            return res.substring(mp.get(rem));

        return "";
    }

    // Driver code
    public static void main(String[] args)
    {
        int numr = 50, denr = 22;
        String res = fractionToDecimal(numr, denr);
        if (res == "")
            System.out.print("No recurring sequence");
        else
            System.out.print("Recurring sequence is "
                             + res);
    }
}

